CREATE OR REPLACE FUNCTION check_resolution()
RETURNS TRIGGER AS $$
DECLARE
    iii numeric;
BEGIN
    IF NEW.resstat = 'Resolved' THEN
        SELECT (0.6 * id.behansc + 0.4 * id.netansc) INTO iii
        FROM investigationdetails id
        WHERE id.invdetreg = OLD.invdetref;

        IF iii > 75 THEN
            RAISE EXCEPTION 'Resolution blocked: Investigation Intensity Index (%). High-risk case requires further review.', iii;
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_check_resolution ON enforcementactions;

CREATE TRIGGER trg_check_resolution
BEFORE UPDATE ON enforcementactions
FOR EACH ROW
WHEN (OLD.resstat IS DISTINCT FROM NEW.resstat)
EXECUTE FUNCTION check_resolution();

